function draw(){ctx.save();if(shake)ctx.translate(rand(-shake,shake),rand(-shake,shake));
const sky=ctx.createLinearGradient(0,0,0,H);sky.addColorStop(0,'#1b2036');sky.addColorStop(.58,'#30304a');sky.addColorStop(1,'#282337');ctx.fillStyle=sky;ctx.fillRect(0,0,W,H);
