ctx.fillStyle='#202237';ctx.beginPath();ctx.moveTo(0,302);for(let x=0;x<=W;x+=48)ctx.lineTo(x,260+Math.sin(x*.018+2)*18+Math.cos(x*.031)*12);ctx.lineTo(W,ground);ctx.lineTo(0,ground);ctx.fill();
// ruined castle on horizon
