// fog ribbons
for(let i=0;i<3;i++){let x=((tick*13+i*370)%(W+260))-130;ctx.globalAlpha=.07;ctx.fillStyle='#c6a9c5';ctx.beginPath();ctx.ellipse(x,330+i*12,105,9,0,0,Math.PI*2);ctx.fill()}ctx.globalAlpha=1;
// shards
for(const s of shards){if(s.taken)continue;let bob=Math.sin(tick*3+s.phase)*4;ctx.save();ctx.translate(s.x,s.y+bob);ctx.rotate(Math.PI/4);ctx.shadowColor='#f4cf83';ctx.shadowBlur=13;ctx.fillStyle='#f4cf83';ctx.fillRect(-5,-5,10,10);ctx.fillStyle='#fff0c1';ctx.fillRect(-2,-4,3,7);ctx.restore();ctx.shadowBlur=0}
// floating stolen hearts
for(const h of hearts){if(h.got)continue;let bob=Math.sin(tick*2.4+h.phase)*7;ctx.save();ctx.translate(h.x,h.y+bob);ctx.shadowColor=h.type==='wolf'?'#a88bff':'#e37ab5';ctx.shadowBlur=20;ctx.fillStyle=h.type==='wolf'?'#a990ff':'#e982bd';heartShape(0,0,13);ctx.restore();ctx.shadowBlur=0;ctx.fillStyle='#ede3ef';ctx.font='9px DM Mono,monospace';ctx.textAlign='center';ctx.fillText(h.type==='wolf'?'WOLF HEART':'DARK HEART',h.x,h.y+29+bob)}
