if(state==='play'&&!hearts.every(h=>h.got)){ctx.fillStyle='#f1e8dc';ctx.globalAlpha=.65;ctx.font='10px DM Mono,monospace';ctx.textAlign='left';ctx.fillText(hearts.find(h=>h.type==='wolf'&&!h.got)?'THE WOLF HEART IS NEAR':'THE DARK HEART WAITS ABOVE',22,28);ctx.globalAlpha=1}
ctx.restore();}
function heartShape(x,y,s){ctx.beginPath();ctx.moveTo(x,y+s*.85);ctx.bezierCurveTo(x-s*1.6,y-s*.05,x-s*1.35,y-s*1.25,x,y-s*.58);ctx.bezierCurveTo(x+s*1.35,y-s*1.25,x+s*1.6,y-s*.05,x,y+s*.85);ctx.fill()}
function drawPlayer(){let x=player.x,y=player.y;ctx.save();if(player.inv>0&&Math.floor(tick*15)%2)ctx.globalAlpha=.38;
if(player.form==='wolf'){
// mighty wolf silhouette
ctx.save();ctx.translate(x+14,y+20);ctx.scale(player.face,1);ctx.fillStyle='#b9a2c6';ctx.shadowColor='#b59bff';ctx.shadowBlur=player.attack?16:4;
ctx.beginPath();ctx.ellipse(0,4,19,12,-.1,0,Math.PI*2);ctx.fill();ctx.beginPath();ctx.arc(13,-6,10,0,Math.PI*2);ctx.fill();ctx.beginPath();ctx.moveTo(7,-13);ctx.lineTo(8,-25);ctx.lineTo(15,-14);ctx.moveTo(16,-13);ctx.lineTo(24,-22);ctx.lineTo(22,-9);ctx.fill();ctx.fillStyle='#ead9e7';ctx.beginPath();ctx.ellipse(20,-4,6,3,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#232033';ctx.beginPath();ctx.arc(16,-8,1.7,0,7);ctx.fill();ctx.strokeStyle='#c6b0d5';ctx.lineWidth=4;ctx.beginPath();ctx.moveTo(-14,4);ctx.quadraticCurveTo(-28,-4,-27,-12+Math.sin(tick*10)*3);ctx.stroke();ctx.fillStyle='#806d8b';for(let i=-1;i<=1;i++){ctx.fillRect(-10+i*12,12,4,10)}if(player.attack>0){ctx.strokeStyle='#e3d6ff';ctx.lineWidth=3;ctx.beginPath();ctx.arc(15,0,27,-1,1);ctx.stroke()}ctx.restore();
}else{
// cloak and human silhouette
ctx.fillStyle='#d5b08a';ctx.beginPath();ctx.arc(x+14,y+8,7.5,0,Math.PI*2);ctx.fill();ctx.fillStyle='#363145';ctx.beginPath();ctx.moveTo(x+7,y+16);ctx.quadraticCurveTo(x+13,y+11,x+21,y+16);ctx.lineTo(x+27,y+37);ctx.quadraticCurveTo(x+14,y+42,x+2,y+37);ctx.fill();ctx.fillStyle='#8c566a';ctx.beginPath();ctx.moveTo(x+7,y+16);ctx.lineTo(x+14,y+20);ctx.lineTo(x+21,y+16);ctx.lineTo(x+25,y+37);ctx.lineTo(x+4,y+37);ctx.fill();ctx.fillStyle='#e9ca9e';ctx.fillRect(x+6,y+35,6,4);ctx.fillRect(x+17,y+35,6,4);ctx.fillStyle='#2c2739';ctx.beginPath();ctx.moveTo(x+5,y+7);ctx.quadraticCurveTo(x+4,y-2,x+14,y-2);ctx.quadraticCurveTo(x+23,y-2,x+23,y+8);ctx.lineTo(x+19,y+6);ctx.lineTo(x+17,y+1);ctx.lineTo(x+13,y+6);ctx.lineTo(x+8,y+5);ctx.fill();if(player.attack>0){ctx.strokeStyle='#fff0c3';ctx.lineWidth=3;ctx.shadowColor='#f4d18c';ctx.shadowBlur=9;ctx.beginPath();ctx.moveTo(x+14+player.face*11,y+20);ctx.lineTo(x+14+player.face*37,y+12);ctx.stroke();ctx.shadowBlur=0}}
ctx.restore()}
function drawEnemy(f){ctx.save();ctx.translate(f.x+f.w/2,f.y+f.h/2);ctx.scale(f.dir,1);ctx.fillStyle='#504056';ctx.beginPath();ctx.ellipse(0,6,13,16,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#a96b7d';ctx.beginPath();ctx.arc(0,-8,11,0,Math.PI*2);ctx.fill();ctx.fillStyle='#32273c';ctx.beginPath();ctx.moveTo(-11,-9);ctx.lineTo(-8,-22);ctx.lineTo(-1,-13);ctx.lineTo(5,-23);ctx.lineTo(10,-10);ctx.fill();ctx.fillStyle='#ffd38f';ctx.fillRect(3,-9,3,3);ctx.restore()}
